 "content": "def transform(grid):
    """Copy the lone patterned compartment into every compartment of a grid."""
    h, w = len(grid), len(grid[0])
    # The separator color forms complete horizontal and/or vertical lines.
    sep_color = None
    for row in grid:
        if len(set(row)) == 1:
            sep_color = row[0]
            break
    if sep_color is None:
        for c in range(w):
            col = [grid[r][c] for r in range(h)]
            if len(set(col)) == 1:
                sep_color = col[0]
                break
    if sep_color is None:
        return [row[:] for row in grid]

    sep_rows = [r for r in range(h) if all(v == sep_color for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep_color for r in range(h))]
    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_spans = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_spans = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]

    # The most frequent non-separator color is the compartment background.
    counts = {}
    for row in grid:
        for value in row:
            if value != sep_color:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    regions = []
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            if r0 < r1 and c0 < c1:
                tile = [row[c0:c1] for row in grid[r0:r1]]
                signal = sum(v != background for row in tile for v in row)
                regions.append((r0, r1, c0, c1, tile, signal))
    if not regions:
        return [row[:] for row in grid]
    source = max(regions, key=lambda item: item[5])
    if source[5] == 0:
        return [row[:] for row in grid]
    pattern = source[4]
    out = [row[:] for row in grid]
    for r0, r1, c0, c1, _tile, _signal in regions:
        for dr, row in enumerate(pattern):
            for dc, value in enumerate(row):
                out[r0 + dr][c0 + dc] = value
    return out
